  s.glasses = Math.random() < .25 ? rnd(META.glasses) : 'none'; s.lens = s.glasses === 'none' ? 'clear' : weighted({ clear: 8, black: 1.6, brown: .3, blue: .15, red: .1, yellow: .1 });
  s.expr = 'neutral'; s.mirror = S.mirror;
